// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amt) public {
        amt = bound(amt, 0, 1 ether);
        vm.deal(address(c), amt);

        bool isOwnerCall = (caller == address(this));

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!isOwnerCall) {
            assertTrue(address(c).balance == amt);
        } else {
            assertTrue(address(c).balance <= amt);
        }
    }
}
